class Pipeline:
    "An ordered plan of commands for one project, with each step's result and a shared terminal transcript."
    FILE = 'pipeline.json'
    KIND = 'pipeline'
    @staticmethod
    def defaults(root): return []
    def __init__(self,
        root,             # the project the commands run in
        python=None,      # the interpreter whose virtual environment they run in; None uses this process's
        env=None,         # an `EnvStore`, or anything with `.get(key)` and `.values(keys)`
        dir=DIR,          # where the plan is written, relative to `root`
    ):
        self.root = Path(root).expanduser().resolve()
        self.python, self.dir = python, dir
        self.env = env if env is not None else EnvStore()
        self.steps = self._load()
        self.results, self.active = {}, ''
        self.pty = self._pump = None
        self._subs, self._auto = set(), True
        self.log = bytearray()
    @property
    def path(self): return self.root/self.dir/self.FILE
    def _load(self):
        try: raw = json.loads(self.path.read_text(encoding='utf-8'))
        except (OSError, ValueError): return self.defaults(self.root)
        steps = raw.get('steps') if isinstance(raw, dict) else raw
        rows = [r for r in (steps or ()) if isinstance(r, dict) and r.get('cmd')]
        out = [Step(id=str(row.get('id') or f'step{i + 1}'),
            label=str(row.get('label') or row.get('id') or 'step'),
            cmd=str(row['cmd']), doc=str(row.get('doc') or ''),
            needs=[str(x) for x in (row.get('needs') or ())],
            argv=[str(x) for x in (row.get('argv') or ())],
            meta=dict(row.get('meta') or {})) for i, row in enumerate(rows)]
        return out or self.defaults(self.root)
    def save(self, steps):
        "Write a new plan and return the state; raises when no step has a command."
        rows = [s for s in (steps or ()) if str((s or {}).get('cmd') or '').strip()]
        if not rows: raise PipelineError('a pipeline needs at least one step with a command')
        self.path.parent.mkdir(parents=True, exist_ok=True)
        self.path.write_text(json.dumps({'steps': rows}, indent=2) + '\n', encoding='utf-8')
        self.steps = self._load()
        return self.state()
    def reset_plan(self):
        "Put the default plan back in memory, leaving the saved file in place."
        self.steps = self.defaults(self.root)
        return self.state()
    def step(self, step_id):
        "The step with this id; raises `PipelineError` for an unknown one."
        found = first(self.steps, lambda s: s.id == str(step_id))
        if found is None: raise PipelineError(f'unknown {self.KIND} step: {step_id}')
        return found
    def needs(self):
        "Every environment key the plan names, once each, in the order the steps name them."
        return list(L(self.steps).attrgot('needs').concat().unique())
    def missing(self, step):
        "The keys this step needs that the environment store cannot supply."
        try: return [k for k in step.needs if not self.env.get(k)]
        except Exception: return [k for k in step.needs if not os.environ.get(k)]
    def _env(self):
        "The child's environment: this process, the project's interpreter, then the store on top."
        env = venv_env(self.python)
        try: env.update({k: str(v) for k, v in self.env.values(self.needs()).items()})
        except Exception: pass
        env.setdefault('PYTHONUNBUFFERED', '1')
        if env.get('TERM') in (None, '', 'dumb'): env['TERM'] = 'xterm-256color'
        return env
    def _row(self, s):
        "One step as a caller sees it: the plan, plus how the last run of it went."
        r = self.results.get(s.id) or {}
        return s.dict() | {
            'status': 'running' if s.id == self.active else (r.get('status') or 'pending'),
            'code': r.get('code'), 'started': r.get('started', 0), 'finished': r.get('finished', 0),
            'missing': self.missing(s)}
    def state(self):
        "The plan, each step's status and the overall progress, as plain data."
        rows = [self._row(s) for s in self.steps]
        failed = first(rows, lambda r: r['status'] == 'failed')
        return {'root': str(self.root), 'kind': self.KIND, 'path': str(self.path),
            'configured': self.path.exists(), 'steps': rows, 'active': self.active,
            'running': bool(self.active), 'auto': self._auto,
            'failed': failed['id'] if failed else '',
            'done': bool(rows) and all(r['status'] in ('passed', 'skipped') for r in rows),
            'needs': self.needs()}
    def subscribe(self):
        "A queue of terminal output for one viewer, starting with everything printed so far."
        q = asyncio.Queue()
        if self.log: q.put_nowait(bytes(self.log))
        self._subs.add(q)
        return q
    def unsubscribe(self, q): self._subs.discard(q)
    def _broadcast(self, data):
        self.log += data
        if len(self.log) > SCROLLBACK: del self.log[:-SCROLLBACK]
        for q in list(self._subs):
            try: q.put_nowait(data)
            except Exception: self._subs.discard(q)
    def write(self, data):
        "Send keystrokes to the running step, for example to answer a password prompt."
        if self.pty is not None and self.pty.alive: self.pty.write(data)
    def resize(self, cols, rows):
        if self.pty is not None: self.pty.resize(rows, cols)
    def tail(self, lines=80):
        "The last `lines` of the transcript as plain text, without colour codes."
        text = strip_ansi(bytes(self.log).decode('utf-8', 'replace'))
        rows = text.replace('\r\n', '\n').replace('\r', '\n').rstrip('\n').split('\n')
        return '\n'.join(rows[-max(1, int(lines)):])
    def _resolve(self, argv, env):
        "The executable to spawn, from this pipeline's interpreter."
        return uv_argv(self.root, argv) or resolve_script(argv, self.python, env)
    async def start(self, step_id='', auto=True):
        "Start one step and, with `auto`, the steps after it while they pass; raises if a step is running."
        if self.active: raise PipelineError(f'{self.active} is still running')
        self._auto = bool(auto)
        step = self.step(step_id) if step_id else self._next()
        if step is None: raise PipelineError('every step has already run — reset to run them again')
        await self._run(step)
        return self.state()
    def _next(self):
        "The first step that has not passed or been skipped."
        done = ('passed', 'skipped')
        return first(self.steps, lambda s: (self.results.get(s.id) or {}).get('status') not in done)
    def _after(self, step):
        i = [s.id for s in self.steps].index(step.id)
        return self.steps[i + 1] if i + 1 < len(self.steps) else None
    async def _run(self, step):
        from ptymini.core import PtySession
        argv = list(step.argv) if step.argv else shlex.split(step.cmd)
        if not argv: raise PipelineError(f'{step.id} has no command to run')
        self.active = step.id
        self.results[step.id] = {'status': 'running', 'code': None,
            'started': int(time.time()), 'finished': 0}
        env = self._env()
        self._broadcast(f'\r\n\x1b[1;36m❯ {step.cmd}\x1b[0m\r\n'.encode())
        try:
            self.pty = PtySession(self._resolve(argv, env), cwd=str(self.root), env=env,
                                  rows=30, cols=100, buffer_bytes=SCROLLBACK)
        except OSError as e:
            self.active = ''
            self.results[step.id] = {'status': 'failed', 'code': None, 'started': int(time.time()),
                'finished': int(time.time()), 'error': str(e)}
            self._broadcast(f'\r\n\x1b[31m{step.cmd}: {e}\x1b[0m\r\n'.encode())
            return
        self._pump = asyncio.create_task(self._drain(step))
    async def _drain(self, step):
        "Pump the step's pty to every viewer, record how it ended, then decide what happens next."
        pty = self.pty
        try:
            async for chunk in pty.attach(from_start=True): self._broadcast(chunk)
        except Exception as e: self._broadcast(f'\r\n\x1b[31m{type(e).__name__}: {e}\x1b[0m\r\n'.encode())
        code = pty.exit_code
        ok = code == 0
        self.results[step.id] = {'status': 'passed' if ok else 'failed', 'code': code,
            'started': (self.results.get(step.id) or {}).get('started', 0),
            'finished': int(time.time())}
        self.active = ''
        note = '\x1b[32m✓ ' if ok else '\x1b[31m✗ '
        self._broadcast(f'\r\n{note}{step.label} exited {code}\x1b[0m\r\n'.encode())
        if ok and self._auto and (nxt := self._after(step)) is not None: await self._run(nxt)
    def stop(self):
        "Kill the running step, mark it failed and stop the run; earlier results stay."
        import signal
        self._auto = False
        step_id, self.active = self.active, ''
        if self.pty is not None and self.pty.alive:
            try: self.pty.kill(signal.SIGTERM)
            except ProcessLookupError: pass
        if step_id:
            self.results[step_id] = (self.results.get(step_id) or {}) | {
                'status': 'failed', 'code': None, 'finished': int(time.time())}
            self._broadcast(f'\r\n\x1b[33m{step_id} stopped\x1b[0m\r\n'.encode())
        return self.state()
    def skip(self, step_id):
        "Mark a step done without running it."
        step = self.step(step_id)
        if self.active == step.id: raise PipelineError(f'{step.id} is still running')
        self.results[step.id] = {'status': 'skipped', 'code': None, 'started': 0,
                                 'finished': int(time.time())}
        return self.state()
    def reset(self):
        "Forget every result and clear the transcript, keeping the plan."
        if self.active: raise PipelineError(f'{self.active} is still running')
        self.results.clear()
        self.log.clear()
        self._broadcast(b'\x1b[2J\x1b[H')
        return self.state()
    def blame(self, checkouts=(), family=None):
        "Which of your packages raised in the last failure, and the file to open in your checkout."
        from pullup.stack import blame as attribute
        if not any((self.results.get(s.id) or {}).get('status') == 'failed' for s in self.steps):
            return {}
        return attribute(self.tail(400), checkouts=checkouts, family=family)

# %% ../nbs/02_pipeline.ipynb #7a1bd528
NOTES_CMDS = ('nbdev-release-gh', 'nbdev_release_gh')
QUIET = '--no-changelog --no-editor --yes'
CLEAN_CMD = 'nbdev-release-git'
MARKER = '<!-- do not remove -->\n'

def project_version(root):
    "The version the next release carries: `settings.ini`, then `pyproject.toml`, then the `__version__` a dynamic version reads; `''` when none names one."
    root = Path(root)
    try: text = (root/'settings.ini').read_text(encoding='utf-8', errors='replace')
    except OSError: text = ''
    if m := re.search(r'^version\s*=\s*(\S+)', text, re.M): return m[1]
    toml = _toml(root); proj = toml.get('project') or {}
    if v := proj.get('version'): return str(v)
    if 'version' not in (proj.get('dynamic') or ()): return ''
    #: nbdev v3 keeps it in the package's `__init__.py`; hatch names that file, else the package is the project's name.
    src = (((toml.get('tool') or {}).get('hatch') or {}).get('version') or {}).get('path') or f"{str(proj.get('name') or '').replace('-', '_')}/__init__.py"
    try: m = re.search(r'''^__version__\s*=\s*['"]([^'"]+)['"]''', (root/src).read_text(encoding='utf-8', errors='replace'), re.M)
    except OSError: return ''
    return m[1] if m else ''

def _sections(txt):
    "The `## ` sections of a changelog in order, as `(heading, body)`."
    return [(h.strip(), body) for h, _, body in (p.partition('\n') for p in re.split(r'^## ', txt, flags=re.M)[1:])]

def _is_ver(heading, ver): return bool(ver) and re.fullmatch(rf'v?{re.escape(ver)}(?![\w.])(?:[\s(\[-].*)?', heading) is not None

def changelog_state(root, version=None):
    "Whether the first section of `CHANGELOG.md`, the one nbdev publishes, is a filled entry for `version` (default: the project's)."
    root = Path(root); version = version or project_version(root)
    out = dict(version=version, path=str(root/'CHANGELOG.md'), has=False, kind='', heading=f'## {version}')
    try: secs = _sections((root/'CHANGELOG.md').read_text(encoding='utf-8'))
    except OSError: return out
    if not secs or not secs[0][1].strip() or not version: return out
    if _is_ver(secs[0][0], version): out |= dict(has=True, kind='version')
    elif secs[0][0].lower() == 'unreleased': out |= dict(has=True, kind='unreleased')
    return out

def claim_unreleased(root, version):
    "Rename the leading `## Unreleased` heading to `## version`; returns the path, or None when there is no such heading."
    path = Path(root)/'CHANGELOG.md'
    try: txt = path.read_text(encoding='utf-8')
    except OSError: return None
    new, n = re.subn(r'^## Unreleased[ \t]*$', f'## {version}', txt, count=1, flags=re.M | re.I)
    if n: path.write_text(new, encoding='utf-8')
    return path if n else None

def write_changelog(root, version, text):
    "Write `text` as the entry for `version`, where nbdev puts one; an entry already there is replaced. Returns the path."
    text, path = str(text or '').strip(), Path(root)/'CHANGELOG.md'
    if not version: raise PipelineError('there is no version to write release notes for')
    if not text: raise PipelineError('the release notes are empty')
    old = path.read_text(encoding='utf-8') if path.exists() else f'# Release notes\n\n{MARKER}'
    old = re.sub(rf'^## v?{re.escape(version)}(?![\w.])[^\n]*(?:\n|\Z).*?(?=^## |\Z)', '', old, flags=re.M | re.S)
    entry = f'## {version}\n\n{text}\n\n'
    if MARKER in old: head, _, rest = old.partition(MARKER); head += MARKER + '\n'
    elif m := re.search(r'^## ', old, re.M): head, rest = old[:m.start()].rstrip('\n') + '\n\n', old[m.start():]
    else: head, rest = (old.rstrip('\n') + '\n\n' if old.strip() else ''), ''
    path.write_text((head + entry + rest.lstrip('\n')).rstrip('\n') + '\n', encoding='utf-8')
    return path

def notes_step(step):
    "Whether `step` is the bare nbdev release command, which stops to ask questions and open an editor."
    return not step.argv and step.cmd.strip() in NOTES_CMDS

def quiet(cmd):
    "The nbdev release command with the flags that stop it asking for an editor or a yes."
    return f'{cmd.strip()} {QUIET}'

def tree_clean(root):
    "Whether git has no tracked change for `nbdev-release-gh` to commit; a folder git cannot read counts as not clean."
    try: r = subprocess.run(['git', 'status', '--porcelain', '--untracked-files=no'], cwd=str(root), capture_output=True, text=True, stdin=subprocess.DEVNULL)
    except OSError: return False
    return r.returncode == 0 and not r.stdout.strip()

def release_cmd(root, cmd):
    "`nbdev-release-git` when there is nothing to commit, as `nbdev-release-gh` would stop there; else the quiet `cmd`."
    return CLEAN_CMD if tree_clean(root) else quiet(cmd)


# %% ../nbs/02_pipeline.ipynb #e22f9231
class Release(Pipeline):
    "The release pipeline, whose default plan is the project's release flow."
    FILE = 'release.json'
    KIND = 'release'
    @staticmethod
    def defaults(root): return default_steps(root)
    def _row(self, s):
        row = super()._row(s)
        return row | ({'notes': (self.results.get(s.id) or {}).get('notes')} if row['status'] == 'needs_notes' else {})
    def state(self):
        flow = release_flow(self.root)
        st = super().state()
        return st | {'flow': flow, 'nbdev': flow == 'nbdev',
            'fastship': flow == 'fastship', 'app': app_project(self.root),
            'notes': first((r['notes'] for r in st['steps'] if r['status'] == 'needs_notes'))}
    async def _run(self, step):
        "Run `step`; the bare nbdev release command runs quiet once the changelog has its entry (as `nbdev-release-git` when the tree is clean), and otherwise waits for notes."
        if not notes_step(step): return await super()._run(step)
        st = changelog_state(self.root)
        if not st['has']:
            self._auto = False
            self.results[step.id] = {'status': 'needs_notes', 'code': None, 'started': 0, 'finished': 0, 'notes': st}
            self._broadcast(f"\r\n\x1b[33m{step.label} waits for release notes for {st['version'] or 'this version'}\x1b[0m\r\n".encode())
            return
        if st['kind'] == 'unreleased': claim_unreleased(self.root, st['version'])
        await super()._run(replace(step, cmd=release_cmd(self.root, step.cmd)))

